mapper.select:
        select  t.tax_rate,t.tax_rate taxRate,t.unit,t.price,t.inv_id,t.inv_id invId,t.num,t.with_tax_flag,t.with_tax_flag withTaxFlag,t.detail_id,t.detail_id detailId,t.tax,t.status_cd,t.status_cd statusCd,t.goods_code,t.goods_code goodsCode,t.goods_name,t.goods_name goodsName 
from plugin_invoice_detail t 
where 1 =1 

   and t.tax_rate= #{taxRate}


   and t.unit= #{unit}


   and t.price= #{price}


   and t.inv_id= #{invId}


   and t.num= #{num}


   and t.with_tax_flag= #{withTaxFlag}


   and t.detail_id= #{detailId}


   and t.tax= #{tax}


   and t.status_cd= #{statusCd}


   and t.goods_code= #{goodsCode}


   and t.goods_name= #{goodsName}

order by t.create_time desc

   limit #{page}, #{row}

